def combinations(a, target):
    a = sorted(a)
    out = []
    def build(i, rem, path):
        if rem == 0:
            out.append(path[:])
            return
        for j in range(i, len(a)):
            if j > i and a[j] == a[j-1]:
                continue
            if a[j] > rem:
                break
            path.append(a[j])
            build(j+1, rem-a[j], path)
            path.pop()
    build(0, target, [])
    return out

